using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BEOFunctionScreens {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");const string p="Assets/Afrer_Seconds/05.Model/Props/B4/";foreach(var k in new[]{25,26,39})AssetDatabase.ImportAsset(p+"Textures/BX_Display_"+k+".png",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var map=new Dictionary<string,int>{{"C01",27},{"W01",34},{"W02",29},{"S01",28}};var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform.Find("B4_실험운용설비");var log=new List<object>();foreach(var rr in root.GetComponentsInChildren<Renderer>()){var t=PrefabUtility.GetNearestPrefabInstanceRoot(rr.gameObject);if(!t||!t.name.Contains("보호관측"))continue;string code=map.Keys.Single(k=>t.name.StartsWith("B4_"+k+"_"));var mm=rr.sharedMaterials;for(int i=0;i<mm.Length;i++)if(mm[i].name=="BX_Display_25"){mm[i]=AssetDatabase.LoadAssetAtPath<Material>(p+"Materials/BX_Display_"+map[code]+".mat");log.Add(new{name=t.name,screen=map[code]});}rr.sharedMaterials=mm;PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));File.WriteAllText(repo+"/SourceAssets/B4_ExperimentOperations/booth_screen_changes.json",JsonConvert.SerializeObject(log,Formatting.Indented));return log;}
}
